/** The engine reads a chain of edits written as one revision takes, its
 * bytes registered as heads of `ref` (the planners take no other: those of
 * `ref`'s page). */
const nativeRevisionChainEngine = (ref: Readonly<{ pageId: string; resourceId: string;
  resourceVersionId: string }>): PdfNativeChainEngine => Object.freeze({
  sectionCount: (bytes: Uint8Array) => createPdfNativePlanners(ref.pageId).readMraiNativePdfXrefSectionCount(bytes),
  squash: (base: Uint8Array, candidate: Uint8Array) =>
    createPdfNativePlanners(ref.pageId).squashMraiNativeRevisions(base, candidate),
  sha256: sha256PdfBytes,
  adopt: (sha256: string) => registerPdfNativeWorkingHead(sha256, ref),
});
