/** A page's managed object rows of one kind (their directives), in order:
 * what a write of that kind would change. */
/** A shaped line's packaged face, verified by its pinned digest. */
async function loadVerifiedComplexScriptFont(sourceId: string): Promise<Uint8Array | null> {
  const loaded = await fetchVerifiedPdfComplexScriptFont(sourceId);
  return loaded ? new Uint8Array(loaded) : null;
}

function managedRowsKey(rows: readonly { readonly text?: unknown }[], prefix: string | readonly string[]): string {
  const prefixes = typeof prefix === "string" ? [prefix] : prefix;
  return JSON.stringify(rows
    .map((row) => row.text)
    .filter((text): text is string => typeof text === "string" && prefixes.some((one) => text.startsWith(one)))
    .sort());
}
