/** How long a "download current version" waits for the reader to answer its
 * annotated-download request before giving it up (a very large PDF builds
 * for minutes; a request no reader picked up must not hold every later one). */
const ANNOTATED_DOWNLOAD_SETTLE_TIMEOUT_MS = 5 * 60_000;
/** The line and the source bytes an editing surface is drawn for. */
/** A reader item's count key: its text and origin in hundredths of a point. */
function pdfReaderItemCountKey(item: Readonly<{ str: string; x: number; y: number }>): string {
  return `${item.str}@${item.x.toFixed(2)},${item.y.toFixed(2)}`;
}

/** The boxes the reader shows of a page of these bytes alone (no block this
 * window keeps), by their words: what a lean written where the text stands
 * is read back by (lean-read-back.ts). */
async function readPdfPageBoxTexts(bytes: Uint8Array, pageNumber: number): Promise<string[]> {
  const pdfjs = await loadCompatiblePdfJs();
  const task = pdfjs.getDocument({ data: Uint8Array.from(bytes), ...PDF_JS_DOCUMENT_ASSETS });
  try {
    const documentProxy = await task.promise;
    try {
      const page = await documentProxy.getPage(pageNumber);
      const content = await readPdfTextContentWithHardGroups(page);
      return nativeParagraphEditBoxesOfTextContent({ pageNumber, content,
        viewport: page.getViewport({ scale: 1 }) as never }).boxes.map((box) => box.text);
    } finally {
      await documentProxy.destroy().catch(() => {});
    }
  } finally {
    await task.destroy().catch(() => {});
  }
}

/** The reader's (pdf.js) items of a page, counted by text and origin: what a
 * planned delete is read back by. */
async function readPdfPageReaderItemCounts(bytes: Uint8Array, pageNumber: number): Promise<Map<string, number>> {
  const pdfjs = await loadCompatiblePdfJs();
  const task = pdfjs.getDocument({ data: Uint8Array.from(bytes), ...PDF_JS_DOCUMENT_ASSETS });
  try {
    const documentProxy = await task.promise;
    try {
      const page = await documentProxy.getPage(pageNumber);
      const counts = new Map<string, number>();
      for (const entry of (await page.getTextContent()).items) {
        if (!("str" in entry) || !entry.str.trim()) continue;
        const key = pdfReaderItemCountKey({ str: entry.str, x: Number(entry.transform[4]), y: Number(entry.transform[5]) });
        counts.set(key, (counts.get(key) ?? 0) + 1);
      }
      return counts;
    } finally {
      await documentProxy.destroy().catch(() => {});
    }
  } finally {
    await task.destroy().catch(() => {});
  }
}

/** Whether a selection holds a whole box of the page as the reader read it:
 * its items, every one, or the one line a box stands for. */
function nativeSelectionIsWholeBox(selection: PdfNativeListTextSelectionEvidence,
  boxes: readonly PdfNativeParagraphEditBox[]): boolean {
  const indexes = (items: readonly Readonly<{ itemIndex: number }>[]) =>
    items.map((item) => item.itemIndex).sort((left, right) => left - right).join(",");
  const wanted = selection.items?.length ? indexes(selection.items) : null;
  return boxes.some((box) => {
    if (wanted !== null) return box.items.length > 1 && indexes(box.items) === wanted;
    if (box.selectionItem) {
      return box.selectionItem.itemIndex === selection.item.itemIndex && box.selectionItem.str === selection.item.str;
    }
    return box.items.length === 1 && box.items[0].itemIndex === selection.item.itemIndex &&
      box.items[0].str === selection.item.str;
  });
}

/**
 * A line's selection found again on other bytes: the same words, starting
 * where they started, on the same page -- a queued edit of a run (its words
 * retyped, its font extended) planned again on the version another tab saved
 * first, where the run itself was written again (a new box's words appended
 * after the peer's). Historical offsets are never reused: the selection is
 * read off the bytes as the reader reads them. Null when the page does not
 * show that run there once (the edit is refused, not planned on a guess).
 */
async function relocatePdfNativeTextSelection(bytes: Uint8Array, sourceSha256: string,
  selection: PdfNativeListTextSelectionEvidence,
  /** A paragraph of several items too, found only where every one of its
   * items reads the same words at the same place (a line opened while the
   * edit before it is handed to the page, on that edit's revision). */
  options: Readonly<{ items?: boolean;
    /** The words the line reads now (an edit just staged on it): found by
     * them where it starts, its items whatever the edit made them. */
    words?: string }> = {}): Promise<PdfNativeListTextSelectionEvidence | null> {
  if (selection.items?.length && !options.items && options.words === undefined) return null;
  const pdfjs = await loadCompatiblePdfJs();
  const task = pdfjs.getDocument({ data: Uint8Array.from(bytes), ...PDF_JS_DOCUMENT_ASSETS });
  try {
    const documentProxy = await task.promise;
    try {
      const page = await documentProxy.getPage(selection.pageNumber);
      const content = await readPdfTextContentWithHardGroups(page);
      const { boxes } = nativeParagraphEditBoxesOfTextContent({ pageNumber: selection.pageNumber, content,
        viewport: page.getViewport({ scale: 1 }) as never });
      return relocatedRunSelectionOn(boxes, sourceSha256, selection, options);
    } finally {
      await documentProxy.destroy().catch(() => {});
    }
  } catch {
    return null;
  } finally {
    await task.destroy().catch(() => {});
  }
}

/**
 * One show of the page found again on other bytes as the reader's own item
 * (pdfNativeReaderItemSelectionOn): a line inside a paragraph, which no box
 * of the page stands for on its own (relocatePdfNativeTextSelection reads
 * boxes). Null when no item, or more than one, reads so.
 */
async function relocatePdfNativeReaderItemSelection(bytes: Uint8Array, sourceSha256: string,
  selection: PdfNativeListTextSelectionEvidence): Promise<PdfNativeListTextSelectionEvidence | null> {
  if (selection.items?.length) return null;
  const pdfjs = await loadCompatiblePdfJs();
  const task = pdfjs.getDocument({ data: Uint8Array.from(bytes), ...PDF_JS_DOCUMENT_ASSETS });
  try {
    const documentProxy = await task.promise;
    try {
      const page = await documentProxy.getPage(selection.pageNumber);
      const content = await page.getTextContent();
      return pdfNativeReaderItemSelectionOn(content.items.filter(
        (entry): entry is Extract<typeof entry, { str: string }> => "str" in entry), sourceSha256, selection);
    } finally {
      await documentProxy.destroy().catch(() => {});
    }
  } catch {
    return null;
  } finally {
    await task.destroy().catch(() => {});
  }
}

/** A staged revision goes up in one tick: parsed, its text built, its page
 * drawn, all off the page first. Off only for a test of the long way, which
 * the reader still falls back to when a revision cannot be read in whole. */
function pdfRevisionCommitEnabled(): boolean {
  return (globalThis as { __mraiPdfRevisionCommit?: boolean }).__mraiPdfRevisionCommit !== false;
}

function nativeTextStagedLineFrame(box: HTMLElement | null, pageNumber: number): PdfNativeLineFrame | null {
  const page = box?.isConnected ? box.closest<HTMLElement>(".pdf-viewer__page") : null;
  if (!box || !page) return null;
  const at = box.getBoundingClientRect(), on = page.getBoundingClientRect();
  if (!(at.width > 0 && at.height > 0 && on.width > 0 && on.height > 0)) return null;
  return Object.freeze({ pageNumber, x: (at.left - on.left) / on.width, y: (at.top - on.top) / on.height,
    width: at.width / on.width, height: at.height / on.height });
}
/** A line left moved or turned, the change being written: where its box
 * stood and where the reader put it (page fractions, its angle in degrees). */
type PdfNativeTextLineMoved = Readonly<{ key: string; lineId: string | null;
  from: Readonly<PageFractionBox & { angle: number }>; to: Readonly<PageFractionBox & { angle: number }> }>;














function notePdfNativeTextLineMoved(input: {
  carry: Readonly<{ from: PageFractionBox; to: PageFractionBox }> | null | undefined;
  shown: Readonly<{ x: number; y: number; width: number; height: number; angle: number }> | null | undefined;
  /** The box as the editor opened on it (its layout's box). */
  opened?: PageFractionBox | null;
  angle: number; key: string; lineId: string | null; box: HTMLElement | null; pageNumber: number;
}): PdfNativeTextLineMoved | null {
  const shown = input.shown && [input.shown.x, input.shown.y, input.shown.width, input.shown.height].every(Number.isFinite) &&
    input.shown.width > 0 && input.shown.height > 0 ? input.shown : null;
  const stoodAt = input.carry?.from ?? (shown ? input.opened ?? null : null);
  if (!stoodAt) return null;
  const from = { x: stoodAt.x, y: stoodAt.y, width: stoodAt.width, height: stoodAt.height, angle: Number(input.angle) || 0 };
  const to = shown
    ? { x: shown.x, y: shown.y, width: shown.width, height: shown.height, angle: Number(shown.angle) || 0 }
    : input.carry ? { ...input.carry.to, angle: from.angle } : null;
  if (!to || !(from.width > 0 && from.height > 0 && to.width > 0 && to.height > 0)) return null;
  const turned = normalizeBoxAngle(to.angle - from.angle);
  const placedElsewhere = Math.abs(to.x - from.x) + Math.abs(to.y - from.y) +
    Math.abs(to.width - from.width) + Math.abs(to.height - from.height) >= 5e-4;
  if (Math.abs(turned) < 0.05 && !(input.carry && placedElsewhere)) return null;
  const stood = nativeTextStagedLineFrame(input.box, input.pageNumber);
  const sx = to.width / from.width, sy = to.height / from.height;
  const placed = stood ? { x: to.x + (stood.x - from.x) * sx, y: to.y + (stood.y - from.y) * sy,
    width: stood.width * sx, height: stood.height * sy } : null;
  // Turned: the frame its box spans there, turned about the editor frame's
  // centre (page fractions are not square: turned in the page's own pixels).
  const on = Math.abs(turned) >= 0.05 && input.box?.isConnected
    ? input.box.closest<HTMLElement>(".pdf-viewer__page")?.getBoundingClientRect() ?? null : null;
  const goesTo = placed && on && on.width > 0 && on.height > 0 ? (() => {
    const centre = { x: (to.x + to.width / 2) * on.width, y: (to.y + to.height / 2) * on.height };
    const corners = [[0, 0], [1, 0], [1, 1], [0, 1]].map(([u, v]) => rotatePointAround(
      { x: (placed.x + placed.width * u) * on.width, y: (placed.y + placed.height * v) * on.height }, centre, turned));
    const left = Math.min(...corners.map(corner => corner.x)), top = Math.min(...corners.map(corner => corner.y));
    return { x: left / on.width, y: top / on.height,
      width: (Math.max(...corners.map(corner => corner.x)) - left) / on.width,
      height: (Math.max(...corners.map(corner => corner.y)) - top) / on.height };
  })() : placed;
  markPdfNativeTextLineGoesTo(input.box, goesTo);
  markPdfTextLatency("detach.moved", { marked: stood !== null,
    dx: Math.round((to.x - from.x) * 1e4) / 1e4, dy: Math.round((to.y - from.y) * 1e4) / 1e4,
    ...(Math.abs(turned) >= 0.05 ? { turned: Math.round(turned * 10) / 10 } : {}) });
  return Object.freeze({ key: input.key, lineId: input.lineId, from: Object.freeze(from), to: Object.freeze(to) });
}
/** The move was not written: the line stays where the page reads it (its box,
 * and the box that has its id on the page now, no longer say it is going). */
function forgetPdfNativeTextLineMoved(moved: PdfNativeTextLineMoved, box: HTMLElement | null, page: ParentNode | null | undefined): void {
  markPdfNativeTextLineGoesTo(box, null);
  if (moved.lineId !== null) markPdfNativeTextLineGoesTo(findPdfNativeTextBoxByLineId(page, moved.lineId), null);
}
function nativeListTextSurfaceKey(selection: PdfNativeListTextSelectionEvidence): string {
  return `${pdfNativeListTextTargetKey(selection)}:${selection.sourceSha256}`;
}

/** A text move refused because the text's own clip would hide where it lands. */
function isNativeTextMoveClipLanding(error: unknown): boolean {
  return error instanceof Error && error.message === MRAI_NATIVE_TEXT_MOVE_REFUSALS.clipLanding;
}









async function planNativeTextMoveLanding(input: Readonly<{
  /** The planners of the page the move is on. */
  planners: PdfNativePlanners;
  sourceBytes: Uint8Array;
  selection: PdfNativeListTextSelectionEvidence;
  move: Readonly<{ x: number; y: number }>;
  groupProven: boolean;
}>): Promise<
  | Readonly<{ kind: "move"; plan: Awaited<ReturnType<PdfNativePlanners["planMraiNativeTextMove"]>> }>
  | Readonly<{ kind: "group"; transform: Readonly<{ a: number; d: number; e: number; f: number }>;
      plan: Awaited<ReturnType<PdfNativePlanners["planMraiNativeTextGroupMove"]>> }>
> {
  try {
    return Object.freeze({ kind: "move" as const, plan: await input.planners.planMraiNativeTextMove({
      sourceBytes: input.sourceBytes, selection: input.selection, move: input.move }) });
  } catch (error) {
    if (!input.groupProven || !isNativeTextMoveClipLanding(error)) throw error;
    const transform = Object.freeze({ a: 1, d: 1, e: input.move.x, f: input.move.y });
    return Object.freeze({ kind: "group" as const, transform, plan: await input.planners.planMraiNativeTextGroupMove({
      sourceBytes: input.sourceBytes, selection: input.selection, transform }) });
  }
}

/** Whether a paragraph format names a face the PDF does not hold yet. */
/**
 * A box's draft leaves it as it was: a move that takes it nowhere, or (no
 * move proof) no property changed. The preview's and the Leave's one test.
 */
function pdfNativeTextDraftLeavesBox(draft: PdfNativeTextPropertyDraft | null,
  proof: PdfNativeListTextSelectionProof | null | undefined, move: PdfNativeTextDraftMove): boolean {
  return move.group || move.move ? !move.changed
    : !pdfNativePropertyDraftChanges(draft, proof?.properties?.original ?? null);
}

function pdfNativeParagraphFormatEmbedsFonts(format: PdfNativeParagraphFormat): boolean {
  return [format.fontResourceName, ...(format.parts ?? []).map((part) => part.fontResourceName)]
    .some((name) => name !== undefined && isPdfNativeEmbeddedFontKey(name));
}







function saveNativeStagedEarly(working: Readonly<{ getSnapshot(): Readonly<{ failure: unknown }>; flush(): Promise<void> }>,
  lane: string, autosave: boolean): void {
  if (!autosave || working.getSnapshot().failure) return;
  markPdfTextLatency(`${lane}.save-early`);
  void Promise.resolve().then(() => working.flush()).catch(() => undefined);
}

/**
 * The drawing of a staged revision taken from the exact previews held as its
 * line was left (holdPdfNativeCandidatePages): only the one whose candidate
 * digest is the staged head's, on the line's source and page, drawn as the
 * host draws its page now. The rest are let go. Null: the page is drawn again.
 */
function takeNativeStagedDrawing(previews: PdfNativeHeldCandidatePages | null | undefined, lane: string,
  input: Readonly<{ sourceSha256: string; pageNumber: number; stagedSha256: string; host: HTMLElement | null }>,
): HTMLCanvasElement | null {
  if (!previews) return null;
  const held = previews.count;
  const drawn = previews.take({ sourceSha256: input.sourceSha256, outputSha256: input.stagedSha256,
    pageNumber: input.pageNumber }, input.host);
  previews.release();
  markPdfTextLatency(`${lane}.drawn-ahead`, { held, used: Boolean(drawn) });
  return drawn;
}

/**
 * A box's paragraph format planned as its preview and its Leave both plan it
 * (`plan` writes one try): as asked; without a lean begun inside a word where
 * the write reads back otherwise; in the substitute face where the
 * paragraph's fonts lack the words (a face the PDF does not hold is
 * installed instead). The preview tried one of the two, the Leave both in
 * turn: a preview refused showed nothing for a format the Leave then wrote.
 */
async function planNativeBoxFormatWrite<T>(format: PdfNativeParagraphFormat, replacementText: string,
  plan: (format: PdfNativeParagraphFormat, substitute: boolean) => Promise<T>,
  /** The PDF's fonts the format may name: a face that cannot set the words
   * is set first in the served family of its build, the whole line in it
   * (pdfNativeParagraphFormatInServedSimilarFaces), before the one
   * substitute face takes the missing letters. */
  fontOptions?: Iterable<PdfNativeTextFontOption>,
  /** The box's text as the page holds it (pdfNativeParagraphFormatInServedSimilarFaces). */
  originalText?: string,
  /** The same format with each italic part that follows other words of its
   * line set in a served italic face, not leaned in its own (see
   * readNativeBoxFormat): tried where the leaned write reads back otherwise. */
  leanInServedFace?: PdfNativeParagraphFormat | null,
  /** The same format with no face named for a weight or a slant it sets: the
   * stroke and the lean drawn on each run's own face, where the text stands
   * (see readNativeBoxFormat). The last try, where every face refuses. */
  drawnInPlace?: PdfNativeParagraphFormat | null,
): Promise<Readonly<{ result: T; leanDropped: boolean; substitute: boolean; servedSimilar?: true; leanServed?: true;
  drawnInPlace?: true }>> {
  let asked = format;
  let leanDropped = false;
  let substitute = false;
  let similarTried = !fontOptions;
  let leanServed = false;
  for (;;) {
    try {
      return Object.freeze({ result: await plan(asked, substitute), leanDropped, substitute,
        ...(leanServed ? { leanServed: true as const } : {}) });
    } catch (error) {
      if (!(error instanceof Error)) throw error;
      // A part leaned in its own face after other words of its line that the
      // reader would read otherwise: in the served italic face instead, as
      
      if (!leanServed && !leanDropped && leanInServedFace && error.message === MRAI_NATIVE_PARAGRAPH_READ_BACK_REFUSAL) {
        asked = leanInServedFace;
        leanServed = true;
        continue;
      }
      // A lean or a rise begun inside a word reads back as a word of its
      // own: the other formats go in, that one said not applied.
      if (!leanDropped && error.message === MRAI_NATIVE_PARAGRAPH_READ_BACK_REFUSAL) {
        const upright = pdfNativeParagraphFormatWithoutMidWordLean(asked, replacementText) ?? asked;
        const flat = pdfNativeParagraphFormatWithoutMidWordRise(upright, replacementText) ?? upright;
        if (flat !== asked) { asked = flat; leanDropped = true; continue; }
      }
      if (!substitute && !pdfNativeParagraphFormatEmbedsFonts(asked) &&
        isMraiNativeListTextMissingGlyphRefusal(error.message)) {
        if (!similarTried) {
          similarTried = true;
          const similar = pdfNativeParagraphFormatInServedSimilarFaces(asked, fontOptions!, replacementText, originalText ?? "");
          if (similar) {
            try {
              return Object.freeze({ result: await plan(similar, false), leanDropped, substitute: false, servedSimilar: true as const });
            } catch {
              // The one substitute face, below.
            }
          }
        }
        substitute = true;
        continue;
      }
      // A bold or an italic set through a face (the PDF's own of the family,
      // a served one) that this paragraph refuses -- it cannot be set again
      // at all (an accent drawn off its letter, a symbol its fonts do not
      // name), or the face lacks its words: the stroke, the lean, on its own
      // face where it stands, as the press sets a family no face is held of.
      // A CMR10 paragraph's 倾斜 named the served CM italic and was said not
      // applied, where a Nimbus paragraph beside it leaned (pdf-walk-1000
      
      if (drawnInPlace) {
        try {
          return Object.freeze({ result: await plan(drawnInPlace, false), leanDropped: false, substitute: false,
            drawnInPlace: true as const });
        } catch (placedError) {
          if (!(placedError instanceof Error)) throw placedError;
        }
      }
      throw error;
    }
  }
}

