/** A family the planner could not embed (lib/pdf/native-embedded-fonts.ts),
 * said in the reader's language; any other error as it is. */
function pdfNativeEmbeddedFontRefusalError(
  error: unknown,
  t: PdfRibbonTranslator,
): unknown {
  const refusal = readPdfNativeEmbeddedFontRefusal(error);
  if (!refusal) return error;
  const family = refusal.family;
  const said = new Error(
    refusal.code === "unknown-family"
      ? t("pdf.nativeTextEdit.fontNotEmbeddable", { family })
      : refusal.code === "missing-glyph"
        ? t("pdf.nativeTextEdit.embeddedFontMissingGlyph", { family, character: refusal.character ?? "" })
        : refusal.code === "unsupported-face"
          ? t("pdf.nativeTextEdit.embeddedFontUnsupported", { family })
          : refusal.code === "unsupported-place"
            ? t("pdf.nativeTextEdit.embeddedFontFormText")
            : t("pdf.nativeTextEdit.embeddedFontUnavailable", { family }),
  );
  // A face missing a character, or a style it cannot embed, is one the
  
  // it): the editor takes the line there instead of saying no.
  if (refusal.code === "missing-glyph" || refusal.code === "unsupported-face") {
    said.name = "PdfNativeEmbeddedFontTakeover";
  }
  return said;
}

/**
 * The file's own bookmark tree, read once per head (by its SHA-256), however
 * often a window projects it again or is mounted again: every run of the
 * Bookmarks pane's effect read the whole outline in the planner worker, and
 * 65 reads of one head queued while a page opened, each waiting 5-7 s ahead
 * of the edits behind them. A read that fails is not kept.
 */
const fileManagedOutlineReads = new Map<string, ReturnType<PdfNativePlanners["readMraiNativeManagedOutline"]>>();
function readFileManagedOutlineOnce(planners: PdfNativePlanners, sha256: string,
  bytes: Uint8Array): ReturnType<PdfNativePlanners["readMraiNativeManagedOutline"]> {
  // By page too: a twin page holding the same bytes reads under its own name.
  const key = `${planners.pageId ?? ""}|${sha256.toLowerCase()}`;
  const held = fileManagedOutlineReads.get(key);
  if (held) return held;
  const read = planners.readMraiNativeManagedOutline(bytes);
  fileManagedOutlineReads.set(key, read);
  // The last few heads only (a head is immutable: its tree never changes).
  while (fileManagedOutlineReads.size > 8) {
    fileManagedOutlineReads.delete(fileManagedOutlineReads.keys().next().value as string);
  }
  read.catch(() => {
    if (fileManagedOutlineReads.get(key) === read) fileManagedOutlineReads.delete(key);
  });
  return read;
}

/**
 * A change of created boxes only, each still a local draft (or new): the
 * window keeps it until the box commits on blur, with no write -- and so no
 * command authority to wait for. Null for any change that is written.
 */
function pdfTextBoxDraftOnlyChange(
  before: readonly PdfTextBoxEdit[],
  proposed: readonly PdfTextBoxEdit[],
  drafts: ReadonlySet<string>,
): { changed: PdfTextBoxEdit[]; removed: PdfTextBoxEdit[] } | null {
  const previousByKey = new Map(before.map((edit) => [`${edit.page}:${edit.id}`, edit] as const));
  const changed = proposed.filter((edit) => previousByKey.get(`${edit.page}:${edit.id}`) !== edit);
  const removed = before.filter((edit) =>
    !proposed.some((candidate) => candidate.page === edit.page && candidate.id === edit.id));
  const draftEligible = (edit: PdfTextBoxEdit) =>
    edit.created === true && !edit.nativeSource && !edit.sourceText && !edit.deleted;
  return changed.length + removed.length > 0 &&
    changed.every((edit) =>
      draftEligible(edit) && (drafts.has(edit.id) || !previousByKey.has(`${edit.page}:${edit.id}`))) &&
    removed.every((edit) => drafts.has(edit.id))
    ? { changed, removed } : null;
}

/** The bytes of one saved version of the page's PDF, for a save to read
 * from them the seals of the boxes it writes (bounded, as every source the
 * window loads to write on). */
async function downloadPdfSourceVersionBytes(
  source: Readonly<{ resourceId: string; resourceVersionId: string }>,
): Promise<{ bytes: Uint8Array }> {
  const url = await apiGet<{ download_url?: string }>(
    `/api/v1/resources/${source.resourceId}/versions/${source.resourceVersionId}/download`,
  );
  return loadBoundedPdfForPageWindowMutation(url.download_url ?? "", fetchPdfSource);
}

/** The same box edit, but for the appearance seal a save stamps on its
 * binding (a deferred write's appearance was drawn before that). */
function sameTextBoxEditApartFromSeal(left: object, right: object): boolean {
  const unsealed = (edit: object) => {
    const sourceText = (edit as { sourceText?: object | null }).sourceText;
    return JSON.stringify(sourceText ? { ...edit, sourceText: { ...sourceText, expectedAppearance: null } } : edit);
  };
  return left === right || unsealed(left) === unsealed(right);
}







function emptyCreatedTextBoxRow(row: unknown): boolean {
  if (!row || typeof row !== "object") return false;
  const record = row as { created?: unknown; deleted?: unknown; text?: unknown; kind?: unknown; latex?: unknown;
    nativeSource?: unknown };
  if (record.created !== true || record.deleted === true || record.nativeSource) return false;
  const text = typeof record.text === "string" ? record.text : "";
  if (text.trim()) return false;
  return !(record.kind === "formula" && typeof record.latex === "string" && record.latex.trim());
}

/** The reasons of a row plan refusal (422, pdf_row_plan) that name the rows
 * themselves rather than the head or the page: a changed row with no
 * directive the writer knows (imported_rows), a row without an id or under
 * another row's (rows_invalid). The other reasons (the page's structure, its
 * fonts, its labels) are about the edit, and the page save takes it. */
const PDF_ROW_PLAN_ROW_REFUSALS: ReadonlySet<string> = new Set(["imported_rows", "rows_invalid"]);
function pdfRowPlanRowRefusal(error: unknown): string | null {
  if (!isApiRequestError(error) || error.status !== 422) return null;
  const reason = error.details?.reason;
  return typeof reason === "string" && PDF_ROW_PLAN_ROW_REFUSALS.has(reason) ? reason : null;
}
function pdfRowIdOf(row: JsonValue): string | null {
  const id = row && typeof row === "object" && !Array.isArray(row) ? (row as { id?: unknown }).id : undefined;
  return typeof id === "string" && id.trim() ? id.trim() : null;
}
/** The key a row is quarantined under: its JSON, so that the same row is not
 * sent again and the row changed is. */
function pdfRowQuarantineKey(row: JsonValue): string {
  try { return JSON.stringify(row) ?? ""; } catch { return ""; }
}
/** Of `rows`, the ones a row-level refusal names and the server never
 * plans: new against `before` (not an edit of a row the head holds) with no
 * `[[MRNOTE_NATIVE_` directive -- every row the writer plans carries one
 * (the server's _managed_directive, _decoration_id, _imported_target) --
 * without an id, or under an id another row has. An edit of a row the head
 * holds is not named: the page save takes it, as before. */
function pdfUnplannableNewRows(rows: readonly JsonValue[], before: readonly JsonValue[]): JsonValue[] {
  const held = new Set(before.map(pdfRowIdOf).filter((id): id is string => id !== null));
  const seen = new Set<string>();
  return rows.filter((row) => {
    const id = pdfRowIdOf(row);
    if (id === null || seen.has(id)) return true;
    seen.add(id);
    if (held.has(id)) return false;
    const text = (row as { text?: unknown }).text;
    return !(typeof text === "string" && text.startsWith("[[MRNOTE_NATIVE_"));
  });
}

/** A copy of the page as drawn with one box's place (page fractions)
 * painted over in the colour most of its edge shows: the page without that
 * box where the exact one cannot be drawn. */
function paintPdfBoxOutOfPageCopy(pageCanvas: HTMLCanvasElement,
  box: Readonly<{ x: number; y: number; width: number; height: number }>,
  /** The share of the edge that must be that one colour (a box on a photo
   * painted flat reads as a patch); none by default. */
  minShare = 0): HTMLCanvasElement | null {
  if (!(pageCanvas.width > 0 && pageCanvas.height > 0)) return null;
  const copy = document.createElement("canvas");
  copy.width = pageCanvas.width; copy.height = pageCanvas.height;
  const context = copy.getContext("2d");
  if (!context) return null;
  try { context.drawImage(pageCanvas, 0, 0); } catch { return null; }
  const pad = Math.max(2, Math.round(pageCanvas.width * 0.002));
  const left = Math.max(0, Math.floor(box.x * copy.width) - pad);
  const top = Math.max(0, Math.floor(box.y * copy.height) - pad);
  const right = Math.min(copy.width, Math.ceil((box.x + box.width) * copy.width) + pad);
  const bottom = Math.min(copy.height, Math.ceil((box.y + box.height) * copy.height) + pad);
  if (!(right > left && bottom > top)) return null;
  // The colour around it: the most common of the pixels just outside.
  const counts = new Map<number, number>();
  const sample = (x0: number, y0: number, w: number, h: number) => {
    if (w <= 0 || h <= 0) return;
    let data: Uint8ClampedArray;
    try { data = context.getImageData(x0, y0, w, h).data; } catch { return; }
    for (let i = 0; i < data.length; i += 16) {
      const key = (data[i] << 16) | (data[i + 1] << 8) | data[i + 2];
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  };
  const ring = Math.max(1, pad);
  sample(left, Math.max(0, top - ring), right - left, Math.min(ring, top));
  sample(left, bottom, right - left, Math.min(ring, copy.height - bottom));
  sample(Math.max(0, left - ring), top, Math.min(ring, left), bottom - top);
  sample(right, top, Math.min(ring, copy.width - right), bottom - top);
  let colour = 0xffffff, best = -1, total = 0;
  for (const [key, count] of counts) { total += count; if (count > best) { best = count; colour = key; } }
  if (minShare > 0 && !(total > 0 && best / total >= minShare)) return null;
  context.fillStyle = `rgb(${(colour >> 16) & 255}, ${(colour >> 8) & 255}, ${colour & 255})`;
  context.fillRect(left, top, right - left, bottom - top);
  return copy;
}








const PDF_HOLD_TEXT_BOX_LAYOUTS = false;
