/** A picture transform that leaves the picture where it is (an opacity
 * write's): the links on it stay too. */
function readerPictureAffineIsIdentityLike(matrix: readonly number[]): boolean {
  const identity = [1, 0, 0, 1, 0, 0];
  return matrix.length === 6 && matrix.every((value, index) => Math.abs(value - identity[index]) < 1e-9);
}

