      const deletedIds = new Set(annotationTombstonesRef.current.map(note => note.id));
      for (const discovered of payload.annotations) {
        const projectionKey = pdfSourceNoteProjectionKey(discovered.nativeSource);
        nativeSourceNoteProjectionRef.current.set(
          projectionKey,
          pdfSourceNoteFingerprint(discovered),
        );
        if (discovered.nativeSource.richText) {
          nativeRichTextNoteKeysRef.current.add(projectionKey);
        } else {
          nativeRichTextNoteKeysRef.current.delete(projectionKey);
        }
      }
