      const before = pdfNativeVectorHistoryEndpointOnStreamOf(
        seed.before,
        seed.after,
      );
      const currentEndpoint = direction === "undo" ? seed.after : before;
      const targetEndpoint = direction === "undo" ? before : seed.after;
      const affine = direction === "undo" ? seed.inverse : seed.forward;
      // Staged on the working copy, a group's members are planned each on
      // the head the one before left (persistNativeVectorMutationPlan).
      const working = nativeWorkingDocumentRef.current;
      const head = working && working.canWrite() ? working.getSnapshot() : null;
