              const planBytes = document.copyBytes();
              let imageOrder: number | null = readerOrder;
              let evidence: PdfNativeEmbeddedImageRemovalEvidence | null = null;
              try {
                const expectedMatrix = targets.imageMatrices?.[readerOrder];
                if (expectedMatrix !== undefined) {
                  imageOrder = resolvePdfNativeEmbeddedImageOrder(await nativePlannersRef.current.listMraiNativeEmbeddedImagePaintMatrices({
                    sourceBytes: planBytes, pageNumber }), { order: readerOrder, matrix: expectedMatrix });
                }
                if (imageOrder !== null) {
                  evidence = (await nativePlannersRef.current.planMraiNativeEmbeddedImageRemoval({ sourceBytes: planBytes,
                    selection: { pageNumber, imageOrder } })).evidence;
                }
              } catch {
                evidence = null;
              } finally {
                planBytes.fill(0);
              }
              if (imageOrder === null || !evidence) {
                stagedDeclined += 1;
                continue;
              }
              const order = imageOrder;
              // Its Undo is read from the record the server stores for it.
              const seed = {} as PdfNativeEmbeddedImageHistorySeed;
              const removal = evidence;
              const id = await stageNativeWorkingEngineCommand({ lease, label: "erase-picture",
                invocation: PDF_CROSS_TAB_COMMANDS.embeddedImageRemoveCommit,
                build: (head, transactionId, sessionRevision, pageContentVersion) => buildPdfNativeEmbeddedImageRemoveCommand({
                  lease: createPdfNativeEmbeddedImageEditLease({ pageId: livePageIdRef.current, pageContentVersion,
                    source: head, pageNumber, imageOrder: order }),
                  currentPageId: livePageIdRef.current, currentPageContentVersion: pageContentVersion, currentSource: head,
                  writable: { writable: nativeListWritableRef.current(), reason: "The PDF page is read-only." },
                  sessionRevision, selectionRevision: Math.max(1, pageContentVersion), transactionId }),
                onPublished: (stored) => {
                  const read = lastPdfNativeEmbeddedImageHistorySeed(stored.collection, {
                    transactionId: stored.transactionId, source: stored.source,
                    outputSha256: stored.outputSha256, evidence: removal });
                  if (read) Object.assign(seed, read);
                } });
