  // reported to its run by lib/pdf/agent-window-format.
  const leaveTextEditModeToReaderRef = useRef(leaveTextEditModeToReader);
  leaveTextEditModeToReaderRef.current = leaveTextEditModeToReader;
  const textEditModeForFormatRef = useRef(textEditMode);
  textEditModeForFormatRef.current = textEditMode;
  useEffect(() => {
    let disposed = false;
    const unregister = registerPdfWindowFormatPage(pageId);
    const intake = () => {
      if (disposed || pageTextFormatJobBusyRef.current || pendingPageTextFormatRef.current) return;
      const job = takePdfWindowFormatJob(pageId);
      if (!job) return;
      pageTextFormatJobBusyRef.current = true;
      pendingPageTextFormatRef.current = pdfWindowFormatHandoff(job, (outcome) => {
        void settlePdfWindowFormatJob(job, outcome).finally(() => {
          pageTextFormatJobBusyRef.current = false;
          intake();
        });
      });
      readerRibbonTabRef.current = "edit";
      if (textEditModeForFormatRef.current) leaveTextEditModeToReaderRef.current("page-text-format");
      else setPageTextFormatRun((run) => run + 1);
    };
    intake();
    const onJob = (event: Event) => {
      if ((event as CustomEvent<{ pageId?: string }>).detail?.pageId === pageId) intake();
    };
    window.addEventListener(PDF_WINDOW_FORMAT_JOB_EVENT, onJob);
    return () => {
      disposed = true;
      window.removeEventListener(PDF_WINDOW_FORMAT_JOB_EVENT, onJob);
      unregister();
    };
  }, [pageId]);

  // Add a drawn ink stroke as an undoable command (idempotent by stroke id).
  const recordAddInkStroke = useCallback(
    (stroke: PdfInkStroke) => {
      {
        return;
      }
      const previousStrokes = [...inkStrokesRef.current];
      const previousTombstones = [...inkStrokeTombstonesRef.current];
      const nextStrokes = [
        ...previousStrokes.filter((entry) => entry.id !== stroke.id),
        asLiveInkStroke(stroke),
      ];
      const nextTombstones = previousTombstones.filter(
        (entry) => entry.id !== stroke.id,
      );
      enqueueNativeInkCommit(
        nextStrokes,
        nextTombstones,
        previousStrokes,
        previousTombstones,
      );
    },
    [enqueueNativeInkCommit, hasWorkspaceWriteAuthority],
  );

  // Remove a stroke as an undoable command; undo re-inserts it at its
  // original position so stroke stacking order survives the round-trip.
  const recordDeleteInkStroke = useCallback(
    (id: string) => {
      const previousStrokes = [...inkStrokesRef.current];
      const previousTombstones = [...inkStrokeTombstonesRef.current];
      const index = previousStrokes.findIndex((s) => s.id === id);
      if (index < 0) return;
      const stroke = previousStrokes[index];
      const nextStrokes = previousStrokes.filter(
        (entry) => entry.id !== stroke.id,
      );
      const nextTombstones = [
        ...previousTombstones.filter(
          (entry) => entry.id !== stroke.id,
        ),
        { ...stroke, deleted: true },
      ];
      enqueueNativeInkCommit(
        nextStrokes,
        nextTombstones,
        previousStrokes,
        previousTombstones,
      );
    },
    [enqueueNativeInkCommit],
  );

  // The Draw tab's Eraser: one drag's erase (the strokes it took, whole or
  // in part, and the pieces the point erasers left) as one undoable
  
  const recordEraseInkStrokes = useCallback(
    (result: PdfInkEraseResult) => {
      if (!hasWorkspaceWriteAuthority()) return;
      const previousStrokes = [...inkStrokesRef.current];
      const previousTombstones = [...inkStrokeTombstonesRef.current];
      const next = planPdfManagedInkErase(previousStrokes, previousTombstones, result);
      if (!next) return;
      enqueueNativeInkCommit(
        next.strokes,
        next.tombstones,
        previousStrokes,
        previousTombstones,
      );
    },
    [enqueueNativeInkCommit, hasWorkspaceWriteAuthority],
  );
